INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_IRISH_HEROIC','Irish Heroic & Legendary Age',-100,400),
 ('PER_CEL_MEDIEVAL_IRISH','Medieval Irish',400,1200)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_KINSELLA_TAIN','primary text','Thomas Kinsella (trans.), The Táin (Oxford University Press, 1969)','Ulster Cycle: Táin Bó Cúailnge and remscéla (foretales)'),
 ('SRC_OHOGAIN_LORE_IRELAND','secondary scholarship','Dáithí Ó hÓgáin, The Lore of Ireland: An Encyclopaedia of Myth, Legend and Romance (Boydell Press, 2006)','Irish heroic cycles, sovereignty figures, and folklore beings')
INSERT INTO _e VALUES
 ('ENT_IRH_ULSTER_CYCLE','The Ulster Cycle (Rúraíocht)','narrative_cycle','collective','Celtic/Irish','heroic saga; the Ulaid; the Táin','B','Medieval Irish heroic-tale corpus centred on the Táin Bó Cúailnge; hub collective for the Ulster heroes. Attested in the Book of the Dun Cow and Book of Leinster.'),
 ('ENT_IRH_FENIAN_CYCLE','The Fenian/Ossianic Cycle (Fiannaíocht)','narrative_cycle','collective','Celtic/Irish','heroic saga; the fian; Fionn and the Fianna','B','Cycle of tales of Fionn mac Cumhaill and the Fianna; hub collective. Attested from Acallam na Senórach onward.'),
 ('ENT_IRH_FOLKLORE','Irish Folklore Beings','collective','collective','Celtic/Irish','fairy-belief; otherworld beings; the síde','C','Hub grouping for post-medieval Irish folk supernatural beings collected in the folklore record (Ó hÓgáin).'),
 ('ENT_IRH_CU_CHULAINN','Cú Chulainn','hero','hero','Celtic/Irish','warrior; champion of Ulster; the ríastrad (warp-spasm)','B','Central hero of the Ulster Cycle; son/earthly aspect of the god Lugh. Attested throughout the Táin (Kinsella).'),
 ('ENT_IRH_CONCHOBAR','Conchobar mac Nessa','hero','hero','Celtic/Irish','king of the Ulaid; Emain Macha','B','Legendary king of Ulster at Emain Macha in the Ulster Cycle.'),
 ('ENT_IRH_MEDB','Medb','hero','hero','Celtic/Irish','queen of Connacht; sovereignty; instigator of the Táin','B','Queen of Connacht whose cattle-raid drives the Táin; carries sovereignty-goddess overtones (Kinsella; Ó hÓgáin).'),
 ('ENT_IRH_FERGUS','Fergus mac Róich','hero','hero','Celtic/Irish','exiled Ulster champion; virility','B','Former king of Ulster exiled to Connacht, a leading warrior of the Táin.'),
 ('ENT_IRH_DEIRDRE','Deirdre','hero','hero','Celtic/Irish','tragic heroine; Longes mac nUislenn','B','Heroine of ''The Exile of the Sons of Uisliu'', a remscél of the Táin.'),
 ('ENT_IRH_SCATHACH','Scáthach','hero','hero','Celtic/Irish','warrior-woman; martial instructor; Alba/Skye','C','Warrior-woman who trains Cú Chulainn and grants the gáe bolga (Tochmarc Emire).'),
 ('ENT_IRH_EMER','Emer','hero','hero','Celtic/Irish','wife of Cú Chulainn; the six gifts','C','Wife of Cú Chulainn, wooed in Tochmarc Emire.'),
 ('ENT_IRH_FIONN','Fionn mac Cumhaill','hero','hero','Celtic/Irish','fian-leader; seer; the salmon of knowledge','B','Central hero of the Fenian Cycle, leader of the Fianna (Ó hÓgáin).'),
 ('ENT_IRH_OISIN','Oisín','hero','hero','Celtic/Irish','poet-warrior; Tír na nÓg','B','Son of Fionn, poet of the Fianna and namesake of the Ossianic Cycle; visits Tír na nÓg.'),
 ('ENT_IRH_DIARMUID','Diarmuid Ua Duibhne','hero','hero','Celtic/Irish','fian warrior; the love-spot (ball seirce)','B','Fenian warrior and foster-son of Aengus; elopes with Gráinne.'),
 ('ENT_IRH_GRAINNE','Gráinne','hero','hero','Celtic/Irish','heroine; betrothed of Fionn; the elopement','B','Daughter of Cormac mac Airt who elopes with Diarmuid (Tóraigheacht Dhiarmada agus Ghráinne).'),
 ('ENT_IRH_PARTHOLON','Partholón','legendary_figure','legendary_figure','Celtic/Irish','invasion leader; second settlement of Ireland','C','Leader of the second invasion of Ireland in the Lebor Gabála Érenn.'),
 ('ENT_IRH_CESAIR','Cesair','legendary_figure','legendary_figure','Celtic/Irish','first settler of Ireland; pre-Flood arrival','C','Granddaughter of Noah and leader of the first (pre-Flood) settlement in the Lebor Gabála Érenn.'),
 ('ENT_IRH_NEMED','Nemed','legendary_figure','legendary_figure','Celtic/Irish','invasion leader; ancestor of later peoples','C','Leader of the third invasion and ancestor of the Fir Bolg and Tuatha Dé in the Lebor Gabála Érenn.'),
 ('ENT_IRH_MILESIANS','The Milesians (Sons of Míl / Meic Míled)','collective','collective','Celtic/Irish','final invasion; Gaelic ancestors of the Irish','C','The Gaels, sons of Míl Easpáine, who take Ireland from the Tuatha Dé in the Lebor Gabála Érenn.'),
 ('ENT_IRH_TUAN','Tuan mac Cairill','legendary_figure','legendary_figure','Celtic/Irish','shapeshifting survivor; witness to the invasions','C','Sole survivor of Partholón''s people who lives through many animal forms and recounts the invasions (Scel Tuain).'),
 ('ENT_IRH_FINTAN','Fintan mac Bóchra','legendary_figure','legendary_figure','Celtic/Irish','shapeshifting sage; the salmon; long memory','C','Husband of Cesair who survives the Flood and ages through the eras as a witness-sage (Lebor Gabála; dindshenchas).'),
 ('ENT_IRH_CAILLEACH','The Cailleach (Cailleach Béirre)','deity','goddess','Celtic/Irish','winter; land-shaping; sovereignty; old age','C','Sovereignty/landscape hag-goddess of winter and the Irish/Scottish-Gaelic countryside (Ó hÓgáin).'),
 ('ENT_IRH_TAILTIU','Tailtiu','deity','goddess','Celtic/Irish','earth/land-clearing; sovereignty; Lughnasa','C','Foster-mother of Lugh whose funeral games at Teltown founded the Lughnasa assembly (dindshenchas).'),
 ('ENT_IRH_CARMAN','Carman','deity','goddess','Celtic/Irish','eponymous goddess; the óenach assembly','C','Fomorian-allied sorceress and eponym of the Carman assembly in Leinster (dindshenchas).'),
 ('ENT_IRH_TLACHTGA','Tlachtga','deity','goddess','Celtic/Irish','eponymous goddess; the Hill of Ward; Samhain fire','C','Daughter of the druid Mug Ruith, eponym of Tlachtga (Hill of Ward) and its Samhain assembly (dindshenchas).'),
 ('ENT_IRH_AOS_SI','The Aos Sí (the síde / fairy folk)','collective','collective','Celtic/Irish','otherworld folk; the síde mounds; the diminished gods','C','The fairy folk of the síde, understood as the diminished Tuatha Dé Danann; the encompassing class of Irish supernatural beings (Ó hÓgáin).'),
 ('ENT_IRH_BANSHEE','The Banshee (bean sí)','folklore_being','spirit','Celtic/Irish','death-omen; keening; the lament','C','''Woman of the síde'' whose keening foretells a death in certain families (Ó hÓgáin).'),
 ('ENT_IRH_LEPRECHAUN','The Leprechaun (luprachaín)','folklore_being','spirit','Celtic/Irish','solitary fairy; shoemaker; hidden gold','C','Solitary fairy cobbler guarding hidden treasure in Irish folklore (Ó hÓgáin).'),
 ('ENT_IRH_PUCA','The Púca','folklore_being','spirit','Celtic/Irish','shapeshifting spirit; mischief; the Samhain blight','C','Shapeshifting Irish nature-spirit, often a black horse, both helpful and malicious (Ó hÓgáin).'),
 ('ENT_IRH_DULLAHAN','The Dullahan','folklore_being','spirit','Celtic/Irish','headless rider; death-herald','C','Headless horseman of Irish folklore who heralds death (Ó hÓgáin).'),
 ('ENT_IRH_CHANGELING','The Changeling (iarlais)','folklore_being','spirit','Celtic/Irish','fairy substitution; the stolen child','C','Fairy substitute left in place of a human (often an infant) stolen by the síde (Ó hÓgáin).');
