INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_IRH_CU_CHULAINN','member_of','ENT_IRH_ULSTER_CYCLE','high','Cú Chulainn is the central hero of the Ulster Cycle (Kinsella, The Táin).'),
 ('ENT_IRH_CONCHOBAR','member_of','ENT_IRH_ULSTER_CYCLE','high','Conchobar mac Nessa is king of the Ulaid in the Ulster Cycle.'),
 ('ENT_IRH_MEDB','member_of','ENT_IRH_ULSTER_CYCLE','high','Medb of Connacht is the antagonist-queen of the Táin within the Ulster Cycle.'),
 ('ENT_IRH_FERGUS','member_of','ENT_IRH_ULSTER_CYCLE','high','Fergus mac Róich is a principal figure of the Ulster Cycle and the Táin.'),
 ('ENT_IRH_DEIRDRE','member_of','ENT_IRH_ULSTER_CYCLE','high','Deirdre is heroine of a remscél of the Táin within the Ulster Cycle.'),
 ('ENT_IRH_SCATHACH','member_of','ENT_IRH_ULSTER_CYCLE','medium','Scáthach appears in Tochmarc Emire as Cú Chulainn''s instructor in the Ulster Cycle.'),
 ('ENT_IRH_EMER','member_of','ENT_IRH_ULSTER_CYCLE','high','Emer is Cú Chulainn''s wife within the Ulster Cycle.'),
 ('ENT_IRH_FIONN','member_of','ENT_IRH_FENIAN_CYCLE','high','Fionn mac Cumhaill is the central hero of the Fenian Cycle (Ó hÓgáin).'),
 ('ENT_IRH_OISIN','member_of','ENT_IRH_FENIAN_CYCLE','high','Oisín, son of Fionn, is namesake of the Ossianic/Fenian Cycle.'),
 ('ENT_IRH_DIARMUID','member_of','ENT_IRH_FENIAN_CYCLE','high','Diarmuid Ua Duibhne is a leading fian warrior in the Fenian Cycle.'),
 ('ENT_IRH_GRAINNE','member_of','ENT_IRH_FENIAN_CYCLE','high','Gráinne is heroine of the Fenian pursuit-tale Tóraigheacht Dhiarmada agus Ghráinne.'),
 ('ENT_IRH_BANSHEE','member_of','ENT_IRH_FOLKLORE','high','The banshee is a core Irish folklore being (Ó hÓgáin, Lore of Ireland).'),
 ('ENT_IRH_LEPRECHAUN','member_of','ENT_IRH_FOLKLORE','high','The leprechaun is a core Irish folklore being.'),
 ('ENT_IRH_PUCA','member_of','ENT_IRH_FOLKLORE','high','The púca is a core Irish folklore being.'),
 ('ENT_IRH_DULLAHAN','member_of','ENT_IRH_FOLKLORE','high','The dullahan is a core Irish folklore death-being.'),
 ('ENT_IRH_CHANGELING','member_of','ENT_IRH_FOLKLORE','high','The changeling is a recurrent Irish fairy-belief motif.'),
 ('ENT_IRH_AOS_SI','member_of','ENT_IRH_FOLKLORE','medium','The aos sí form the encompassing class of the Irish folklore otherworld beings.'),
 ('ENT_IRH_CU_CHULAINN','child_of','ENT_CEL_LUGH','high','Cú Chulainn is the son (and earthly aspect) of the god Lugh in the Ulster Cycle (Kinsella; Ó hÓgáin).'),
 ('ENT_IRH_CU_CHULAINN','reception_of','ENT_CEL_LUGH','medium','Cú Chulainn functions as a heroic, euhemerised reflex of the divine Lugh.'),
 ('ENT_IRH_CU_CHULAINN','taught_by','ENT_IRH_SCATHACH','high','Scáthach trains Cú Chulainn in arms and gives him the gáe bolga (Tochmarc Emire).'),
 ('ENT_IRH_EMER','consort_of','ENT_IRH_CU_CHULAINN','high','Emer is the wife of Cú Chulainn (Tochmarc Emire).'),
 ('ENT_IRH_FERGUS','consort_of','ENT_IRH_MEDB','medium','Fergus is the lover of Medb during his Connacht exile in the Táin.'),
 ('ENT_IRH_OISIN','child_of','ENT_IRH_FIONN','high','Oisín is the son of Fionn mac Cumhaill.'),
 ('ENT_IRH_DIARMUID','child_of','ENT_CEL_AENGUS','medium','Diarmuid is the foster-son of the god Aengus, who protects him in the pursuit-tale (Ó hÓgáin).'),
 ('ENT_IRH_GRAINNE','consort_of','ENT_IRH_DIARMUID','high','Gráinne elopes with and becomes the partner of Diarmuid.'),
 ('ENT_IRH_FIONN','opposes','ENT_IRH_DIARMUID','medium','Fionn pursues Diarmuid and Gráinne after their elopement in the Fenian pursuit-tale.'),
 ('ENT_IRH_PARTHOLON','opposes','ENT_CEL_FOMORIANS','medium','Partholón''s people battle the Fomorians in the Lebor Gabála invasion sequence.'),
 ('ENT_IRH_NEMED','opposes','ENT_CEL_FOMORIANS','high','Nemed and his descendants war against the Fomorians in the Lebor Gabála Érenn.'),
 ('ENT_IRH_MILESIANS','opposes','ENT_CEL_TUATHA','high','The Sons of Míl defeat the Tuatha Dé Danann and take Ireland in the Lebor Gabála Érenn.'),
 ('ENT_IRH_TUAN','member_of','ENT_IRH_FOLKLORE','low','Tuan mac Cairill, the shapeshifting survivor, belongs to the broader Irish legendary/lore stratum; tying him into a hub for connectivity.'),
 ('ENT_IRH_FINTAN','consort_of','ENT_IRH_CESAIR','medium','Fintan mac Bóchra is the husband of Cesair in the Lebor Gabála Érenn.'),
 ('ENT_IRH_CESAIR','member_of','ENT_IRH_MILESIANS','low','Cesair belongs to the invasion-sequence lore; wiring her to the invasion hub for connectivity (note: distinct from the Gaelic Milesians proper, linked only as invasion stratum).'),
 ('ENT_IRH_PARTHOLON','opposes','ENT_IRH_NEMED','low','Partholón and Nemed are successive invasion leaders in the same Lebor Gabála sequence; linking the invasion figures for graph connectivity.'),
 ('ENT_IRH_TAILTIU','parent_of','ENT_CEL_LUGH','high','Tailtiu is the foster-mother of the god Lugh, whose funeral games became Lughnasa (Ó hÓgáin).'),
 ('ENT_IRH_CARMAN','opposes','ENT_CEL_TUATHA','medium','The Fomorian-allied sorceress Carman and her sons are driven off by the Tuatha Dé in the dindshenchas.'),
 ('ENT_IRH_CAILLEACH','aligned_with','ENT_IRH_TAILTIU','low','The Cailleach and Tailtiu are both sovereignty/landscape goddesses of the Irish countryside; grouped functionally.'),
 ('ENT_IRH_TLACHTGA','aligned_with','ENT_IRH_CARMAN','low','Tlachtga and Carman are both eponymous landscape goddesses of Irish assembly-sites in the dindshenchas.'),
 ('ENT_IRH_AOS_SI','reception_of','ENT_CEL_TUATHA','high','The aos sí are understood in later tradition as the diminished Tuatha Dé Danann withdrawn into the síde (Ó hÓgáin).'),
 ('ENT_IRH_BANSHEE','member_of','ENT_IRH_AOS_SI','medium','The bean sí (''woman of the síde'') is a member of the fairy folk.');
INSERT INTO entity_relationships(subject_entity_id,relationship_type,object_entity_id,confidence,rationale,source_id,review_status)
